		},
	}
	cmd.Flags().IntVar(&limit, "limit", defaultEntitiesLimit, "Maximum matching entities")
	cmd.Flags().StringVar(&branch, "branch", "", "Only report commits reachable from this branch (default: every indexed commit)")
